mapper.select:
SELECT po_no, supplier_id, operator_id, order_date, delivery_place, status, remark
FROM purchase_order
WHERE po_no = #{poNo}

mapper.update:
UPDATE purchase_order
SET supplier_id    = #{supplierId},
    order_date     = #{orderDate},
    delivery_place = #{deliveryPlace},
    remark         = #{remark}
WHERE po_no = #{poNo}

UPDATE purchase_order
SET status = #{status}
WHERE po_no = #{poNo}
